static int digitValue(char c)
{
    if (c >= '0' && c <= '9')
        return c - '0';
    if (c >= 'A' && c <= 'F')
        return c - 'A' + 10;
    return c - 'a' + 10;
}

int main(void)
{
    int r, m, i, len, k = 0;
    long long dec = 0, tmp;
    char s[32];
    char out[64];

    if (scanf("%d %d", &r, &m) != 2)
        return 0;
    if (scanf("%31s", s) != 1)
        return 0;

    len = (int)strlen(s);
    for (i = 0; i < len; i++)
        dec = dec * r + digitValue(s[i]);

    printf("%lld\n", dec);

    tmp = dec;
    if (tmp == 0) {
        out[k++] = '0';
    } else {
        while (tmp > 0) {
            int dig = (int)(tmp % m);
            out[k++] = (char)(dig < 10 ? '0' + dig : 'A' + dig - 10);
            tmp /= m;
        }
    }

    for (i = k - 1; i >= 0; i--)
        putchar(out[i]);
    putchar('\n');
    return 0;
}

