#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int value;
    int count;
} Group;

static int cmpIntAsc(const void *a, const void *b)
{
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

static int cmpGroup(const void *a, const void *b)
{
    const Group *p = (const Group *)a;
    const Group *q = (const Group *)b;

    if (p->count != q->count)
        return q->count - p->count;          /* 次数多的在前 */
    return (p->value > q->value) - (p->value < q->value);
}

int main(void)
{
    int a[200];
    Group g[200];
    int n, i, k = 0;

    if (scanf("%d", &n) != 1)
        return 0;
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);

    qsort(a, (size_t)n, sizeof(a[0]), cmpIntAsc);

    for (i = 0; i < n; i++) {
        if (k > 0 && g[k - 1].value == a[i]) {
            g[k - 1].count++;
        } else {
            g[k].value = a[i];
            g[k].count = 1;
            k++;
        }
    }

    qsort(g, (size_t)k, sizeof(g[0]), cmpGroup);

    for (i = 0; i < k; i++) {
        int j;
        for (j = 0; j < g[i].count; j++) {
            if (i > 0 || j > 0)
                printf(" ");
            printf("%d", g[i].value);
        }
    }
    printf("\n");
    return 0;
}

