#include <stdio.h>

/* 反转区间 [begin, end) */
static void reverseRange(int *begin, int *end)
{
    if (begin >= end)          /* 空区间直接返回 */
        return;
    --end;                     /* 现在 end 指向区间内最后一个元素 */
    while (begin < end) {
        int t = *begin;
        *begin = *end;
        *end = t;
        ++begin;
        --end;
    }
}

int main(void)
{
    int a[100];
    int n, k, i;

    if (scanf("%d %d", &n, &k) != 2)
        return 0;
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);

    k %= n;                       /* k 可能大于 n */

    reverseRange(a, a + k);       /* 前 k 个反转 */
    reverseRange(a + k, a + n);   /* 后 n-k 个反转 */
    reverseRange(a, a + n);       /* 整体反转 */

    for (i = 0; i < n; i++) {
        if (i > 0)
            printf(" ");
        printf("%d", a[i]);
    }
    printf("\n");
    return 0;
}

