#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *createNode(int value)
{
    Node *p = (Node *)malloc(sizeof(Node));

    if (p == NULL)
        return NULL;
    p->value = value;
    p->next = NULL;
    return p;
}

static Node *buildList(int n)
{
    Node *head = NULL, *tail = NULL;
    int i, value;

    for (i = 0; i < n; i++) {
        Node *p;
        if (scanf("%d", &value) != 1)
            break;
        p = createNode(value);
        if (p == NULL)
            break;
        if (head == NULL) {
            head = tail = p;
        } else {
            tail->next = p;
            tail = p;
        }
    }
    return head;
}

static Node *mergeList(Node *a, Node *b)
{
    Node dummy;                       /* 哑结点，省掉头指针的特判 */
    Node *tail = &dummy;

    dummy.next = NULL;
    while (a != NULL && b != NULL) {
        if (a->value <= b->value) {
            tail->next = a;
            a = a->next;
        } else {
            tail->next = b;
            b = b->next;
        }
        tail = tail->next;
    }
    tail->next = (a != NULL) ? a : b;
    return dummy.next;
}

static void destroyList(Node *head)
{
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void)
{
    int n1, n2, printed = 0;
    Node *a, *b, *c, *p;

    if (scanf("%d %d", &n1, &n2) != 2)
        return 0;

    a = buildList(n1);
    b = buildList(n2);
    c = mergeList(a, b);

    for (p = c; p != NULL; p = p->next) {
        if (printed > 0)
            printf(" ");
        printf("%d", p->value);
        printed++;
    }
    if (printed == 0)
        printf("empty");
    printf("\n");

    destroyList(c);
    return 0;
}

