typedef struct {
    int id;
    char name[20];
    int total;
} Student;

static int cmpStudent(const void *a, const void *b)
{
    const Student *p = (const Student *)a;
    const Student *q = (const Student *)b;

    if (p->total != q->total)
        return q->total - p->total;        /* 总分高的在前 */
    return (p->id > q->id) - (p->id < q->id);   /* 总分相同，学号小的在前 */
}

int main(void)
{
    Student stu[100];
    int n, i;

    if (scanf("%d", &n) != 1)
        return 0;

    for (i = 0; i < n; i++) {
        int s1, s2, s3;
        scanf("%d %19s %d %d %d", &stu[i].id, stu[i].name, &s1, &s2, &s3);
        stu[i].total = s1 + s2 + s3;
    }

    qsort(stu, (size_t)n, sizeof(stu[0]), cmpStudent);

    for (i = 0; i < n; i++)
        printf("%d %s %d\n", stu[i].id, stu[i].name, stu[i].total);
    return 0;
}

