{
    const ClassStat *p = (const ClassStat *)a;
    const ClassStat *q = (const ClassStat *)b;

    return (p->id > q->id) - (p->id < q->id);
}

int main(void)
{
    ClassStat st[100];
    int n, k = 0, i;

    if (scanf("%d", &n) != 1)
        return 0;

    for (i = 0; i < n; i++) {
        int cid, score, j, pos = -1;
        char name[32];

        scanf("%d %31s %d", &cid, name, &score);

        for (j = 0; j < k; j++) {
            if (st[j].id == cid) {
                pos = j;
                break;
            }
        }
        if (pos < 0) {
            pos = k++;
            st[pos].id = cid;
            st[pos].count = 0;
            st[pos].sum = 0;
            st[pos].best = -1;
        }
        st[pos].count++;
        st[pos].sum += score;
        if (score > st[pos].best)
            st[pos].best = score;
    }

    qsort(st, (size_t)k, sizeof(st[0]), cmpById);

    for (i = 0; i < k; i++)
        printf("%d %d %.1f %d\n", st[i].id, st[i].count,
               (double)st[i].sum / st[i].count, st[i].best);
    return 0;
}

