#include <iostream>
#include <iomanip>
#include <map>
#include <string>
using namespace std;

struct Stat {
    int count = 0;
    int sum = 0;
    int best = -1;
};

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n))
        return 0;

    map<int, Stat> groups;          // 键是班级号，map 自动按升序排列
    for (int i = 0; i < n; ++i) {
        int cid, score;
        string name;
        cin >> cid >> name >> score;
        Stat &s = groups[cid];
        s.count++;
        s.sum += score;
        if (score > s.best)
            s.best = score;
    }

    cout << fixed << setprecision(1);
    for (const auto &kv : groups) {
        const Stat &s = kv.second;
        cout << kv.first << ' ' << s.count << ' '
             << static_cast<double>(s.sum) / s.count << ' '
             << s.best << '\n';
    }
    return 0;
}
